import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'changeme-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token', '')
        if not token:
            return jsonify({'error': 'missing token'}), 401
        parts = token.split('.')
        if len(parts) != 2:
            return jsonify({'error': 'invalid token format'}), 401
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/reports', methods=['GET'])
@verify_api_token
def get_reports():
    """Fetch reports with optional filtering by department and date range."""
    department = request.args.get('dept', '')
    start_date = request.args.get('start', '2020-01-01')
    end_date = request.args.get('end', '2099-12-31')
    sort_col = request.args.get('sort', 'created_at')

    # Build query with parameterized dates but dynamic sort
    base_query = "SELECT id, title, department, author, created_at, summary FROM reports"
    conditions = []
    params = []

    if department:
        conditions.append("department = ?")
        params.append(department)

    conditions.append("created_at BETWEEN ? AND ?")
    params.extend([start_date, end_date])

    where_clause = " WHERE " + " AND ".join(conditions)

    # Sort column - validated against allowlist... but the allowlist check has a flaw
    allowed_sorts = ['created_at', 'title', 'department', 'author']
    if sort_col.split()[0].lower() not in [x.lower() for x in allowed_sorts]:
        sort_col = 'created_at'

    # The ORDER BY is concatenated directly - the allowlist check above
    # only validates the first word, allowing injection after a space
    query = base_query + where_clause + f" ORDER BY {sort_col}"

    try:
        db = get_db()
        cursor = db.execute(query, params)
        rows = cursor.fetchall()
        results = [dict(row) for row in rows]
        return jsonify({'reports': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/v1/reports/<int:report_id>', methods=['GET'])
@verify_api_token
def get_report_detail(report_id):
    db = get_db()
    cursor = db.execute("SELECT * FROM reports WHERE id = ?", (report_id,))
    row = cursor.fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/api/v1/export', methods=['POST'])
@verify_api_token
def export_reports():
    """Export filtered reports to CSV. Uses same query logic."""
    data = request.get_json(force=True)
    department = data.get('dept', '')
    sort_col = data.get('sort', 'created_at')

    allowed_sorts = ['created_at', 'title', 'department', 'author']
    if sort_col.split()[0].lower() not in [x.lower() for x in allowed_sorts]:
        sort_col = 'created_at'

    query = f"SELECT id, title, department, author, created_at FROM reports ORDER BY {sort_col}"

    try:
        db = get_db()
        cursor = db.execute(query)
        rows = cursor.fetchall()
        lines = ['id,title,department,author,created_at']
        for row in rows:
            lines.append(','.join(str(v) for v in row))
        return '\n'.join(lines), 200, {'Content-Type': 'text/csv'}
    except Exception as e:
        app.logger.error(f"Export error: {e}")
        return jsonify({'error': 'export failed'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
